function checkModelBuild(p)
%CHECKMODELBUILD  Error if HPP.slx was built for other asset counts than p.
%   HPP.slx contains one Model block per asset instance, generated by
%   buildHPP for the N values in HPP_parameters. Case sets cannot change N;
%   this check stops a run that would silently use the wrong structure.

    load_system("HPP");
    ws = get_param("HPP", "ModelWorkspace");
    if ~hasVariable(ws, "buildInfo")
        error("checkModelBuild:noInfo", "HPP.slx has no build info. Rebuild it with buildHPP.");
    end
    b = getVariable(ws, "buildInfo");
    want = [p.wt.N, p.pv.N, p.bess.N];
    have = [b.N_wt, b.N_pv, b.N_bess];
    if ~isequal(want, have)
        msg = sprintf("HPP.slx was built for N = %d wind, %d PV, %d BESS, but the parameters have %d, %d, %d. " + ...
            "Run buildHPP to rebuild it for the current N.", have, want);
        error("checkModelBuild:mismatch", "%s", msg);
    end
end
